Q: Solve Vendor and Device Ids to Names in C# A: <p>Ok so A.S.M.Nesar Uddin has given a great base line. It has issues however.</p>
<p>It skips Sub Folders.
The Vendors need to return Mfg and not DeviceDesc
The Vendors sometimes return the wrong name.</p>
<p>Beneath you find expanded code based on his answer that fully displays interesting information</p>
<p>(I still wish to thank him however for pointing me in the right direction.
So once he has made some slight corrections on his code I will mark his as the answer, despite this code already doing what I want)</p>
<pre><code>using Microsoft.Win32;
using Vortice.DXGI;

namespace DxGPUReader;
internal class Program
{
    static void Main(string[] args)
    {
        DisplayGPUInfos();
    }

    public static void DisplayGPUInfos()
    {
        using (IDXGIFactory6 factory = DXGI.CreateDXGIFactory2&lt;IDXGIFactory6&gt;(false))
        {
            for (uint i = 0; ; ++i)
            {
                // Enum adapters until DXGI_ERROR_NOT_FOUND
                var result1 = factory.EnumAdapters1(i, out IDXGIAdapter1 adapter);
                if (result1.Failure)
                    break;

                using (adapter)
                {
                    AdapterDescription1 desc = adapter.Description1;

                    // Skip software adapters (like Microsoft Basic Render Driver)
                    if ((desc.Flags &amp; AdapterFlags.Software) != 0)
                        continue;

                    var readValues = GetDesiredInformationFromId(desc.VendorId, desc.DeviceId, desc.SubsystemId, desc.Revision);

                    Console.WriteLine($&quot;GPU {i}: {desc.Description}&quot;);
                    Console.WriteLine(&quot;  Vendor&quot;);
                    Console.WriteLine($&quot;    Vendor ID: {desc.VendorId}&quot;);
                    Console.WriteLine($&quot;    Vendor ID Decoded: {readValues.hexValues.hexVendorId}&quot;);
                    Console.WriteLine($&quot;    Vendor: {readValues.hklmValues.mfg}&quot;);

                    Console.WriteLine(&quot;  Device&quot;);
                    Console.WriteLine($&quot;    Device ID: {desc.DeviceId}&quot;);
                    Console.WriteLine($&quot;    Device ID Decoded: {readValues.hexValues.hexDeviceId}&quot;);
                    Console.WriteLine($&quot;    Device: {readValues.hklmValues.deviceDesc}&quot;);

                    Console.WriteLine(&quot;  SubSystem&quot;);
                    Console.WriteLine($&quot;    Subsystem ID: {desc.SubsystemId}&quot;);
                    Console.WriteLine($&quot;    Subsystem ID Decoded: {readValues.hexValues.hexSubSysId}&quot;);

                    Console.WriteLine(&quot;  Revision&quot;);
                    Console.WriteLine($&quot;    Revision ID: {desc.Revision}&quot;);
                    Console.WriteLine($&quot;    Revision ID Decoded: {readValues.hexValues.hexRevId}&quot;);

                    Console.WriteLine(&quot;  Paths&quot;);
                    Console.WriteLine($&quot;    PIN Path: {readValues.hklmSearchPath}&quot;);
                    Console.WriteLine($&quot;    Driver SubPath: {readValues.hklmValues.driver}&quot;);

                    Console.WriteLine(&quot;  Memory&quot;);
                    Console.WriteLine($&quot;    Dedicated Video Memory: {desc.DedicatedVideoMemory / (1024 * 1024)} MB&quot;);
                    Console.WriteLine($&quot;    Dedicated System Memory: {desc.DedicatedSystemMemory / (1024 * 1024)} MB&quot;);
                    Console.WriteLine($&quot;    Shared System Memory: {desc.SharedSystemMemory / (1024 * 1024)} MB&quot;);
                    Console.WriteLine();
                }
            }
        }

        Console.ReadKey();
    }

    public static
        (string hklmSearchPath, (string hexVendorId, string hexDeviceId, string hexSubSysId, string hexRevId) hexValues,
        (string deviceDesc, string driver, string mfg) hklmValues)
        GetDesiredInformationFromId(uint vendorId, uint deviceId, uint subSystem, uint revId)
    {
        string vendorHex = vendorId.ToString(&quot;X4&quot;);
        string deviceHex = deviceId.ToString(&quot;X4&quot;);
        string subSysHex = subSystem.ToString(&quot;X4&quot;);
        string revHex = revId.ToString(&quot;X2&quot;);

        (string, string, string, string) hexVals = (vendorHex, deviceHex, subSysHex, revHex);

        string basePath = @&quot;SYSTEM\CurrentControlSet\Enum\&quot;;
        //PCI\VEN_8086&amp;DEV_5912&amp;SUBSYS_82BF103C&amp;REV_04
        string pciPath = @$&quot;PCI\VEN_{vendorHex}&amp;DEV_{deviceHex}&amp;SUBSYS_{subSysHex}&amp;REV_{revHex}&quot;;
        string searchPath = basePath + pciPath;

        (string, string, string) vals = GetDesiredInformationFromPath(basePath, pciPath);

        (string hklmSearchPath, (string hexVendorId, string hexDeviceId, string hexSubSysId, string hexRevId) hexValues,
                (string deviceDesc, string driver, string mfg) hklmValues) values
            = (searchPath, hexVals, vals);

        return values;
    }

    public static (string, string, string) GetDesiredInformationFromPath(string basePath, string pciPath)
    {
        string[] requiredNames = [&quot;DeviceDesc&quot;, &quot;Driver&quot;, &quot;Mfg&quot;];
        string deviceDescValue = &quot;Unable to determine DeviceDesc&quot;;
        string driverValue = &quot;Unable to determine Driver&quot;;
        string mfgValue = &quot;Unable to determine Mfg&quot;;

        using (RegistryKey key = Registry.LocalMachine.OpenSubKey(basePath))
        {
            using (RegistryKey gpuKey = key.OpenSubKey(pciPath))
            {
                foreach (string instanceKeyName in gpuKey.GetSubKeyNames())
                {
                    //PCI\VEN_8086&amp;DEV_5912&amp;SUBSYS_82BF103C&amp;REV_04\3&amp;11583659&amp;0&amp;10
                    using (RegistryKey instanceKey = gpuKey.OpenSubKey(instanceKeyName))
                    {
                        string[] valueNames = instanceKey.GetValueNames();
                        bool hasAllRequiredNames = true;
                        foreach (string requiredName in requiredNames)
                        {
                            if (!valueNames.Contains(requiredName))
                            {
                                hasAllRequiredNames = false;
                                break;
                            }
                        }

                        if (!hasAllRequiredNames)
                            continue;

                        try
                        {
                            deviceDescValue = instanceKey.GetValue(requiredNames[0]) as string ?? deviceDescValue;
                            driverValue = instanceKey.GetValue(requiredNames[1]) as string ?? driverValue;
                            mfgValue = instanceKey.GetValue(requiredNames[2]) as string ?? mfgValue;

                            if (deviceDescValue.Contains(&quot;;&quot;))
                                deviceDescValue = deviceDescValue.Split(';').Last();

                            if (mfgValue.Contains(&quot;;&quot;))
                                mfgValue = mfgValue.Split(';').Last();
                        }
                        catch (Exception e)
                        {
                            deviceDescValue = &quot;Error occured trying to determine DeviceDesc&quot;;
                            driverValue = &quot;Error occured trying to determine Driver&quot;;
                            mfgValue = &quot;Error occured trying to determine Mfg&quot;;
                        }
                    }
                }

            }
        }

        (string, string, string) vals = (deviceDescValue, driverValue, mfgValue);

        return vals;
    }
}
</code></pre>
